    m = int(next(it))
    u = int(next(it))
    k = int(next(it))
    diff = [[0] * (m + 2) for _ in range(n + 2)]
    for _ in range(u):
        r1 = int(next(it))
        c1 = int(next(it))
        r2 = int(next(it))
        c2 = int(next(it))
        v = int(next(it))
        diff[r1][c1] += v
        diff[r1][c2 + 1] -= v
        diff[r2 + 1][c1] -= v
        diff[r2 + 1][c2 + 1] += v

    a = [[0] * (m + 1) for _ in range(n + 1)]
    pref = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        drow = diff[i]
        arow = a[i]
        aprev = a[i - 1]
        prow = pref[i]
        pprev = pref[i - 1]
        d_acc = 0
        p_acc = 0
        for j in range(1, m + 1):
            d_acc += drow[j]
            val = aprev[j] + d_acc
            arow[j] = val
            p_acc += val
            prow[j] = pprev[j] + p_acc

    ans = None
    for i in range(k, n + 1):
        prow = pref[i]
        ptop = pref[i - k]
        for j in range(k, m + 1):
            s = prow[j] - ptop[j] - prow[j - k] + ptop[j - k]
            if ans is None or s > ans:
                ans = s
    sys.stdout.write(f"{ans}\n")


